#!/usr/bin/env python3
# lifeplus-site-v4: トップに社訓・デイのご利用時間
# 何度流しても同じ。元のファイルが想定と違うときは何も変えずに止まる
import hashlib, zlib, base64, json, os, shutil, sys, time
FILES = json.loads('{"docs/site.css": {"old": "6d774dcdf128eb08baa399913b070e7c", "new": "acd0b1ee12429825449b8717fff0996e", "data": ""}, "docs/index.html": {"old": "0e318834a9416c9cb08bd64c9eb17063", "new": "3207b7f216b42a2346538119f6ab363b", "data": ""}, "docs/dayservice/index.html": {"old": "9a63d70ea3942bdc76756b5e9ee4edb2", "new": "6b50a8170c04f12840d76a9e143d8975", "data": ""}, "docs/sekkotsu/index.html": {"old": "7a90b53ea8cb153e01b5171459dc4436", "new": "afc4a91ea9650078d138dfd783c3360f", "data": ""}, "docs/bodycare/index.html": {"old": "ff8673dc1d74d58d94e59677171ae627", "new": "11f3769c8f666d31d484bf52b4e5b6e1", "data": ""}, "README.md": {"old": "3abbdce0424f3271ade8ff771ed2e692", "new": "8485bbb1aafde3f90e803779ce10eab1", "data": ""}}')
here = os.path.dirname(os.path.abspath(__file__)); os.chdir(here)
md5 = lambda b: hashlib.md5(b).hexdigest()
todo = []
for p, f in FILES.items():
    cur = md5(open(p, "rb").read()) if os.path.exists(p) else None
    if cur == f["new"]: print("済み", p); continue
    if cur != f["old"]: print("止めました：", p, "が想定と違います（", cur, "）。何も変えていません"); sys.exit(1)
    todo.append(p)
ts = time.strftime("%Y%m%d%H%M%S")
for p in todo:
    shutil.copy2(p, p + ".bak_" + ts)
    b = zlib.decompress(base64.b64decode(FILES[p]["data"]))
    assert md5(b) == FILES[p]["new"]
    open(p, "wb").write(b); print("更新", p)
print("lifeplus-site-v4 OK")
